package com.blockchain.defi

import scala.collection.mutable
import java.security.MessageDigest
import java.util.concurrent.locks.ReentrantReadWriteLock

sealed trait TenantContext {
  def tenantId: String
  def nonce: Long
}

case class ValidatedTenant(tenantId: String, nonce: Long, signature: Array[Byte]) extends TenantContext

trait LiquidityPool {
  def getReserve(token: String, tenant: TenantContext): BigDecimal
  def updateReserve(token: String, amount: BigDecimal, tenant: TenantContext): Unit
}

class IsolatedLiquidityPool extends LiquidityPool {
  private val reserves = mutable.Map[String, mutable.Map[String, BigDecimal]]()
  private val lock = new ReentrantReadWriteLock()

  def getReserve(token: String, tenant: TenantContext): BigDecimal = {
    lock.readLock().lock()
    try {
      reserves.getOrElse(tenant.tenantId, mutable.Map.empty).getOrElse(token, BigDecimal(0))
    } finally {
      lock.readLock().unlock()
    }
  }

  def updateReserve(token: String, amount: BigDecimal, tenant: TenantContext): Unit = {
    require(amount >= BigDecimal(0), "Reserve amount must be non-negative")
    lock.writeLock().lock()
    try {
      val tenantReserves = reserves.getOrElseUpdate(tenant.tenantId, mutable.Map.empty)
      tenantReserves(token) = amount
    } finally {
      lock.writeLock().unlock()
    }
  }

  def initializePool(tenant: TenantContext, tokenA: String, tokenB: String, amountA: BigDecimal, amountB: BigDecimal): Unit = {
    require(amountA > BigDecimal(0) && amountB > BigDecimal(0), "Initial reserves must be positive")
    updateReserve(tokenA, amountA, tenant)
    updateReserve(tokenB, amountB, tenant)
  }
}

class PriceOracle(pool: IsolatedLiquidityPool) {
  private val snapshotPrices = mutable.Map[String, BigDecimal]()

  def captureSnapshot(tokenA: String, tokenB: String, tenant: TenantContext): Unit = {
    val reserveA = pool.getReserve(tokenA, tenant)
    val reserveB = pool.getReserve(tokenB, tenant)
    val price = if (reserveA == BigDecimal(0)) BigDecimal(0) else reserveB / reserveA
    snapshotPrices(s"${tenant.tenantId}:$tokenA:$tokenB") = price
  }

  def getSpotPrice(tokenA: String, tokenB: String, tenant: TenantContext): BigDecimal = {
    snapshotPrices.getOrElse(s"${tenant.tenantId}:$tokenA:$tokenB", BigDecimal(0))
  }
}

class CollateralVault(oracle: PriceOracle, pool: IsolatedLiquidityPool) {
  private val positions = mutable.Map[String, mutable.Map[String, BigDecimal]]()
  private val loans = mutable.Map[String, mutable.Map[String, BigDecimal]]()
  private val COLLATERAL_RATIO = BigDecimal("1.5")

  def deposit(user: String, token: String, amount: BigDecimal, tenant: TenantContext): Unit = {
    require(amount > BigDecimal(0), "Deposit amount must be positive")
    val userPositions = positions.getOrElseUpdate(s"${tenant.tenantId}:$user", mutable.Map.empty)
    userPositions(token) = userPositions.getOrElse(token, BigDecimal(0)) + amount
  }

  def getCollateralValue(user: String, baseToken: String, tenant: TenantContext): BigDecimal = {
    val userPositions = positions.getOrElse(s"${tenant.tenantId}:$user", mutable.Map.empty)
    userPositions.map { case (token, amount) =>
      if (token == baseToken) amount
      else amount * oracle.getSpotPrice(token, baseToken, tenant)
    }.sum
  }

  def borrow(user: String, token: String, amount: BigDecimal, tenant: TenantContext): Either[String, BigDecimal] = {
    require(amount > BigDecimal(0), "Borrow amount must be positive")
    val collateralValue = getCollateralValue(user, token, tenant)
    val existingLoans = loans.getOrElse(s"${tenant.tenantId}:$user", mutable.Map.empty).getOrElse(token, BigDecimal(0))
    val totalLoan = existingLoans + amount
    if (collateralValue >= totalLoan * COLLATERAL_RATIO) {
      val userLoans = loans.getOrElseUpdate(s"${tenant.tenantId}:$user", mutable.Map.empty)
      userLoans(token) = totalLoan
      Right(amount)
    } else {
      Left("Insufficient collateral")
    }
  }
}

class FlashLoanProvider(pool: IsolatedLiquidityPool) {
  private val activeLoans = mutable.Map[String, BigDecimal]()
  private val FEE_BPS = 9 // 0.09% fee

  def executeFlashLoan(
    token: String,
    amount: BigDecimal,
    tenant: TenantContext,
    callback: (BigDecimal, TenantContext) => BigDecimal
  ): Either[String, BigDecimal] = {
    if (amount <= BigDecimal(0)) return Left("Flash loan amount must be positive")
    val currentReserve = pool.getReserve(token, tenant)
    if (amount > currentReserve) return Left("Insufficient liquidity")

    val loanKey = s"${tenant.tenantId}:$token"
    activeLoans(loanKey) = amount

    // Disburse loan - update pool reserve
    pool.updateReserve(token, currentReserve - amount, tenant)

    // Execute borrower's callback
    val returnedAmount = callback(amount, tenant)

    val fee = amount * FEE_BPS / BigDecimal(10000)
    val requiredReturn = amount + fee

    // Verify repayment by checking pool state
    val finalReserve = pool.getReserve(token, tenant)
    activeLoans.remove(loanKey)

    if (finalReserve >= currentReserve + fee) {
      Right(fee)
    } else {
      // Revert: restore original reserve
      pool.updateReserve(token, currentReserve, tenant)
      Left("Flash loan not repaid")
    }
  }
}

class SwapEngine(pool: IsolatedLiquidityPool) {
  def swap(tokenIn: String, tokenOut: String, amountIn: BigDecimal, tenant: TenantContext): BigDecimal = {
    require(amountIn > BigDecimal(0), "Swap input amount must be positive")
    val reserveIn = pool.getReserve(tokenIn, tenant)
    val reserveOut = pool.getReserve(tokenOut, tenant)
    // Constant product AMM: x * y = k
    val amountOut = (reserveOut * amountIn) / (reserveIn + amountIn)
    require(amountOut <= reserveOut, "Insufficient output liquidity")
    pool.updateReserve(tokenIn, reserveIn + amountIn, tenant)
    pool.updateReserve(tokenOut, reserveOut - amountOut, tenant)
    amountOut
  }
}

